def plan_jobs(jobs, now, limit):
    if limit <= 0:
        return []
    eligible = [
        job for job in jobs
        if job.get('state') == 'queued' and job['due'] <= now
    ]
    eligible.sort(key=lambda job: (job['due'], job['id']))
    return [job['id'] for job in eligible[:limit]]

